use vstd::prelude::*;

verus! {
    fn array_to_sequence(arr: &[bool; 10]) -> (res: Vec<bool>)
        requires
            arr.len() == 10,
        ensures
            res.len() == 10,
            forall|k: nat| 0 <= k < 10 ==> res[k] == arr[k],
    {
        let mut res: Vec<bool> = Vec::with_capacity(10);
        let mut idx: usize = 0;

        while idx < 10
            invariant
                idx <= 10,
                res.len() == idx,
                forall|k: nat| 0 <= k < idx ==> res[k] == arr[k],
            decreases 10 - idx,
        {
            res.push(arr[idx]);
            idx = idx + 1;
        }
        
        // Ensure the length of the vector is exactly 10
        assert(res.len() == 10);
        res
    }
}

